SELECT * FROM strategy
WHERE status = 1
  AND id != #{strategyId}

    AND category = #{category}

ORDER BY read_count DESC, collect_count DESC
LIMIT #{limit}

SELECT s.* FROM strategy s
INNER JOIN strategy_collection sc ON s.id = sc.strategy_id
WHERE sc.user_id = #{userId}
ORDER BY sc.created_at DESC
LIMIT #{offset}, #{limit}
